// Generated by clash-webshare-chain. Re-run the tool after subscription
// updates instead of editing the PROFILE_NODES block by hand.
//
// Traffic for Antigravity's Google API domains goes:
//   airport exit (verified) -> Webshare static residential -> target
//
// Webshare accepts only specific airport exit IPs.  Every other exit completes
// the TCP handshake and then stalls on the authenticated CONNECT (about 5s,
// ending in a TLS error), so only end-to-end verified exits are listed here.
// PROFILE_NODES is keyed by profile name and ordered fastest first.

const RESIDENTIAL_PROXY = "Webshare · Static Residential";
const ANTIGRAVITY_GROUP = "Antigravity · Residential Chain";
const UPSTREAM_GROUP = "Webshare · 上游";

const WEBSHARE = {
  server: "__SERVER__",
  port: __PORT__,
  username: "__USERNAME__",
  password: "__PASSWORD__",
};

const PROFILE_NODES = __PROFILE_NODES__;

// For subscriptions that have never been measured on this machine: patterns
// for exits that were verified at some point in the past.  Extend as needed.
const FALLBACK_PATTERNS = [
  /美国0[1-8]-0\.1倍/, // 赔钱机场: 美国01-08 0.1倍
  /^美国USLA-A$/, // 魔界: 美国USLA-A
];

function countOptions(group) {
  return (group.proxies || group.all || []).length;
}

function main(config, profileName) {
  const groups = config["proxy-groups"] || [];

  // Every subscription names its main selector differently (赔钱机场:
  // 🚀节点选择, 魔界: 节点选择, 白嫖机场: 白嫖机场).  Fall back to the
  // largest plain selector, excluding GLOBAL (it contains every group).
  const knownSelectors = ["🚀节点选择", "节点选择", "PROXY", "Proxy"];
  let mainSelector = groups.find((group) => knownSelectors.includes(group.name));
  if (!mainSelector) {
    mainSelector =
      groups
        .filter((group) => group.type === "select" && group.name !== "GLOBAL")
        .sort((a, b) => countOptions(b) - countOptions(a))[0] || null;
  }
  const mainSelectorName = mainSelector ? mainSelector.name : null;

  // Give the Gemini group its own selectable US node when that profile has one.
  const usGoogleNode = "美国LA-优化3-GPT";
  const gemini = groups.find((group) => group.name === "Gemini");
  if (
    gemini &&
    mainSelectorName &&
    (config.proxies || []).some((proxy) => proxy.name === usGoogleNode)
  ) {
    gemini.proxies = [usGoogleNode, mainSelectorName];
  }

  // Idempotent: strip anything a previous run injected.
  config.proxies = (config.proxies || []).filter(
    (proxy) => proxy.name !== RESIDENTIAL_PROXY,
  );
  const legacyGroups = [ANTIGRAVITY_GROUP, UPSTREAM_GROUP, "Webshare · 上游(美国)"];
  config["proxy-groups"] = groups.filter(
    (group) => legacyGroups.indexOf(group.name) === -1,
  );

  const leaves = config.proxies || [];
  const names = leaves.map((proxy) => proxy.name);

  // Prefer the measured list for the active profile.  If Clash Verge passes a
  // uid instead of a name, fall back to any profile whose nodes exist here.
  let pinned = (PROFILE_NODES[profileName] || []).filter(
    (name) => names.indexOf(name) !== -1,
  );
  if (!pinned.length) {
    Object.keys(PROFILE_NODES).some((key) => {
      const hit = PROFILE_NODES[key].filter(
        (name) => names.indexOf(name) !== -1,
      );
      if (hit.length) {
        pinned = hit;
        return true;
      }
      return false;
    });
  }

  const options = pinned.slice();
  if (!options.length) {
    FALLBACK_PATTERNS.forEach((pattern) => {
      names.forEach((name) => {
        if (pattern.test(name) && options.indexOf(name) === -1) {
          options.push(name);
        }
      });
    });
  }
  if (!options.length && mainSelectorName) {
    options.push(mainSelectorName);
  }

  config["proxy-groups"].push({
    name: UPSTREAM_GROUP,
    type: "select",
    proxies: options,
  });

  config.proxies.push({
    name: RESIDENTIAL_PROXY,
    type: "http",
    server: WEBSHARE.server,
    port: WEBSHARE.port,
    username: WEBSHARE.username,
    password: WEBSHARE.password,
    udp: false,
    "dialer-proxy": UPSTREAM_GROUP,
  });

  config["proxy-groups"].push({
    name: ANTIGRAVITY_GROUP,
    type: "select",
    proxies: [RESIDENTIAL_PROXY, UPSTREAM_GROUP],
    "disable-udp": true,
  });

  const antigravityRules = [
    `DOMAIN,generativelanguage.googleapis.com,${ANTIGRAVITY_GROUP}`,
    `DOMAIN,daily-cloudcode-pa.googleapis.com,${ANTIGRAVITY_GROUP}`,
    `DOMAIN,cloudcode-pa.googleapis.com,${ANTIGRAVITY_GROUP}`,
  ];
  config.rules = antigravityRules.concat(config.rules || []);

  return config;
}
